local FlatterMaker = {}
local PRODUCTS = {
    iron_flatter = { name = "Železni ploščato kladivo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ploščato kladivo za kovace." },
    bronze_flatter = { name = "Bronast ploščato kladivo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ploščato kladivo za kovace." },
    silver_flatter = { name = "Srebrn ploščato kladivo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ploščato kladivo za kovace." },
    gilded_flatter = { name = "Pozlačen ploščato kladivo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ploščato kladivo za kovace." },
    jewel_set_flatter = { name = "Draguljast ploščato kladivo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ploščato kladivo za kovace." },
    royal_sovereign_flatter = { name = "Kraljevski suveren ploščato kladivo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ploščato kladivo z biseri za krono." },
}
local BUILDINGS = {
    flatter_workshop = { name = "Flatter delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    flatter_house = { name = "Flatter hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_flatter_atelier = { name = "Mojstrski flatter atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_flatter_palace = { name = "Suverena flatter palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FlatterMaker.ironStock=18; FlatterMaker.bronzeStock=14; FlatterMaker.woodStock=10; FlatterMaker.leatherStock=8; FlatterMaker.silverStock=8; FlatterMaker.goldStock=6; FlatterMaker.jewelStock=4; FlatterMaker.pearlStock=4
FlatterMaker.productStock = {}; FlatterMaker.buildings = {}; FlatterMaker.maker = nil; FlatterMaker.activeMaking = {}; FlatterMaker.totalProducts = 0; FlatterMaker.dayTimer = 0
function FlatterMaker.init() FlatterMaker.ironStock=18; FlatterMaker.bronzeStock=14; FlatterMaker.woodStock=10; FlatterMaker.leatherStock=8; FlatterMaker.silverStock=8; FlatterMaker.goldStock=6; FlatterMaker.jewelStock=4; FlatterMaker.pearlStock=4; FlatterMaker.productStock={}; FlatterMaker.buildings={}; FlatterMaker.maker=nil; FlatterMaker.activeMaking={}; FlatterMaker.totalProducts=0; FlatterMaker.dayTimer=0; print("[FlatterMaker] Royal Flatter Maker System initialized (6 products, 4 buildings)") end
function FlatterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FlatterMaker.maker={name=n or ("Ploščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ploščar najet: %s (spretnost: %d)",FlatterMaker.maker.name,s),"success") end; return true end
function FlatterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FlatterMaker.build(id) local ok,e=FlatterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FlatterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FlatterMaker.getQualityBonus() local b=0; for _,bd in ipairs(FlatterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FlatterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FlatterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FlatterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FlatterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FlatterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FlatterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FlatterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FlatterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FlatterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FlatterMaker.buildings==0 then return false,"Potrebna ploščna delavnica" end; if not FlatterMaker.maker then return false,"Potreben ploščar" end; return true end
function FlatterMaker.make(pt,qty) qty=qty or 1; local ok,e=FlatterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FlatterMaker.ironStock=FlatterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FlatterMaker.bronzeStock=FlatterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FlatterMaker.woodStock=FlatterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FlatterMaker.leatherStock=FlatterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FlatterMaker.silverStock=FlatterMaker.silverStock-d.silverCost*qty end; if d.goldCost then FlatterMaker.goldStock=FlatterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FlatterMaker.jewelStock=FlatterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FlatterMaker.pearlStock=FlatterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FlatterMaker.maker then t=math.max(1,t-math.floor(FlatterMaker.maker.skill/13)) end; table.insert(FlatterMaker.activeMaking,{id="flatter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FlatterMaker.completeMaking(m) local q=1.0+(FlatterMaker.getQualityBonus()/100); if FlatterMaker.maker then q=q+(FlatterMaker.maker.skill/140) end; q=math.min(2.5,q); FlatterMaker.productStock[m.productType]=(FlatterMaker.productStock[m.productType] or 0)+m.quantity; FlatterMaker.totalProducts=FlatterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FlatterMaker.maker then FlatterMaker.maker.itemsMade=FlatterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FlatterMaker.maker.skill=math.min(100,FlatterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plošček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"flatter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FlatterMaker.update(dt) if not _G.state then return end; FlatterMaker.dayTimer=FlatterMaker.dayTimer+dt; if FlatterMaker.dayTimer>=30 then FlatterMaker.dayTimer=0; for i=#FlatterMaker.activeMaking,1,-1 do local m=FlatterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FlatterMaker.completeMaking(m); table.remove(FlatterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FlatterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FlatterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FlatterMaker.getStats() return {ironStock=FlatterMaker.ironStock,bronzeStock=FlatterMaker.bronzeStock,woodStock=FlatterMaker.woodStock,leatherStock=FlatterMaker.leatherStock,silverStock=FlatterMaker.silverStock,goldStock=FlatterMaker.goldStock,jewelStock=FlatterMaker.jewelStock,pearlStock=FlatterMaker.pearlStock,productStock=FlatterMaker.productStock,numBuildings=#FlatterMaker.buildings,hasMaker=FlatterMaker.maker~=nil,makerName=FlatterMaker.maker and FlatterMaker.maker.name or "—",makerSkill=FlatterMaker.maker and FlatterMaker.maker.skill or 0,activeMaking=#FlatterMaker.activeMaking,totalProducts=FlatterMaker.totalProducts} end
return FlatterMaker
